(()=>{'use strict';
const approvalScreen=document.body.dataset.screen==='approvals';
if(!approvalScreen&&new URLSearchParams(location.search).get('role')==='ed'){const target=new URL('fuel-approvals.html',location.href);target.search=location.search;target.searchParams.delete('role');location.replace(target.href);return;}
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search),key='ice-fuel-procurement-v1'+(params.get('scenario')?'-demo-'+params.get('scenario'):'');let lang=params.get('lang')==='km'?'km':'en',role=approvalScreen?'ed':params.get('role')==='entry'?'entry':'ga',tab=params.get('tab')==='history'?'history':'today',day=params.get('date')||localDate(),modal=null,draft={},busy=false,notice='',failNext=params.get('scenario')==='save-error',loadError=false,historyPage=1,approvalFilter='pending';
const L=(en,km)=>lang==='km'?km:en,E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=v=>Number(v).toLocaleString(lang==='km'?'km-KH':'en-GB',{maximumFractionDigits:6}),lit=v=>`${n(v)} ${L('L','លីត្រ')}`,money=v=>`${n(v)} KHR`,id=()=>crypto.randomUUID(),stamp=()=>new Date().toISOString();
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Phnom_Penh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
// Explicit demonstration truck records; production integration reads these fields from Logistics.
const sampleTruckTypes={'TRK-001':'diesel','TRK-002':'petroleum','TRK-003':'super'};
const trucks=window.IceDispatchData.trips.slice(0,3).map((t,i)=>({id:`TRK-00${i+1}`,plate:t.truck,route:t.route,fuelType:sampleTruckTypes[`TRK-00${i+1}`]}));
// Read-only Settings adapter. Prices are sample values, not factory rates.
const fuelSettings={version:'sample-settings-fuels-2',prices:{petroleum:4500,super:4800,diesel:4200}};
if(params.get('scenario')==='missing-type')trucks[0].fuelType=null;
if(params.get('scenario')==='missing-price')fuelSettings.prices.diesel=null;
const fuelTypes=['petroleum','super','diesel'];
function fuelName(type){return ({petroleum:L('Petroleum','សាំងធម្មតា'),super:L('Super petroleum','សាំងស៊ុបពែរ'),diesel:L('Diesel','ប្រេងម៉ាស៊ូត')})[type]||L('Fuel type needed','ត្រូវការប្រភេទប្រេង');}
function fuelOf(row){const type=Object.hasOwn(row,'fuelType')?row.fuelType:trucks.find(t=>t.id===row.truck)?.fuelType;return fuelTypes.includes(type)?type:null;}
function fuelLabel(row){if(row.legacyFuel)return `<span class="fuel-label muted">${L('Fuel type unavailable','មិនមានប្រភេទប្រេង')}</span>`;return `<span class="fuel-label ${fuelOf(row)?'':'error'}">${fuelName(fuelOf(row))}</span>`;}
function frozenRow(row){return {...savedRow(row),fuelType:fuelOf(row),runs:runsFor(row).map(r=>({...r,routeName:structuredClone(routeFor(r))}))};}
function fuelBreakdown(rows,changes=[]){
 const lines=fuelTypes.map(type=>({type,litres:0,price:fuelSettings.prices[type],cost:0,pending:0,requests:0}));let unknown=0,unknownPending=0;
 for(const row of rows){const line=lines.find(x=>x.type===fuelOf(row));if(line)line.litres+=truckLitres(row);else unknown+=truckLitres(row);}
 for(const a of changes){const line=lines.find(x=>x.type===(Object.hasOwn(a,'fuelType')?a.fuelType:fuelOf(a.after)));if(line){line.pending+=a.delta;line.requests++;}else unknownPending+=1;}
 for(const line of lines){const valid=Number.isFinite(line.price)&&line.price>0;line.cost=line.litres===0?0:valid?line.litres*line.price:null;}
 const complete=unknown===0&&lines.every(x=>x.cost!==null);
 return {lines,unknown,unknownPending,complete,cost:complete?lines.reduce((v,x)=>v+x.cost,0):null};
}
function dayBreakdown(d){return fuelBreakdown(effectiveRows(d),pending(d));}
function costLabel(b){return b.complete?money(b.cost):L('Cost incomplete','ថ្លៃគណនាមិនពេញលេញ');}
function fuelSummary(b,saved=false){
 const pendingAny=b.lines.some(x=>x.requests)||b.unknownPending;
 return `<section class="card fuel-summary"><div class="section-head od-field"><h2>${saved?L('Saved fuel breakdown','ព័ត៌មានប្រេងបានរក្សាទុក'):L('Procurement by fuel type','ការទិញតាមប្រភេទប្រេង')}</h2><span class="sub">${saved?L('Quantities and applied prices at recording','បរិមាណ និងតម្លៃនៅពេលកត់ត្រា'):L('Settings prices · sample values · KHR/L','តម្លៃពីការកំណត់ · តម្លៃគំរូ · KHR/លីត្រ')}</span></div><table><thead><tr><th>${L('Fuel type','ប្រភេទប្រេង')}</th><th>${saved?L('Saved litres','លីត្ររក្សាទុក'):L('Approved litres','លីត្របានអនុម័ត')}</th><th>${L('Price (KHR/L)','តម្លៃ (KHR/លីត្រ)')}</th><th>${L('Calculated cost','ថ្លៃគណនា')}</th></tr></thead><tbody>${b.lines.map(x=>`<tr><th scope="row">${fuelName(x.type)}${!saved&&x.requests?`<span class="pending-text">${L('Pending change','ការកែប្រែរង់ចាំ')}: ${x.pending>0?'+':''}${lit(x.pending)}</span>`:''}</th><td data-label="${saved?L('Saved litres','លីត្ររក្សាទុក'):L('Approved litres','លីត្របានអនុម័ត')}">${lit(x.litres)}</td><td data-label="${L('Price (KHR/L)','តម្លៃ (KHR/លីត្រ)')}">${Number.isFinite(x.price)&&x.price>0?n(x.price):`<span class="error">${L('Price needed','ត្រូវការតម្លៃ')}</span>`}</td><td data-label="${L('Calculated cost','ថ្លៃគណនា')}">${x.cost===null?L('Unavailable','មិនមាន'):money(x.cost)}</td></tr>`).join('')}</tbody></table>${b.unknown?`<p class="warning fuel-warning">${L('Fuel type needed','ត្រូវការប្រភេទប្រេង')}: ${lit(b.unknown)} · ${L('Configure the truck record before recording a purchase.','កំណត់ប្រភេទប្រេងលើកំណត់ត្រារថយន្ត មុនកត់ត្រាការទិញ។')}</p>`:''}${b.unknownPending?`<p class="warning fuel-warning">${L('Pending request has no fuel type configured.','សំណើរង់ចាំមិនទាន់កំណត់ប្រភេទប្រេង។')}</p>`:''}<div class="fuel-total od-row"><strong>${L('Total cost','ថ្លៃសរុប')}</strong><strong>${costLabel(b)}</strong></div>${!b.complete?`<p class="error fuel-warning">${L('Resolve missing fuel types or required prices in their source records. A complete purchase cannot be recorded yet.','បំពេញប្រភេទប្រេង ឬតម្លៃដែលខ្វះនៅកំណត់ត្រាប្រភព។ មិនទាន់អាចកត់ត្រាការទិញពេញលេញបានទេ។')}</p>`:''}${!saved&&pendingAny?`<p class="sub fuel-warning">${L('Pending changes are excluded from approved litres and cost.','ការកែប្រែរង់ចាំមិនបានបញ្ចូលក្នុងលីត្រ និងថ្លៃបានអនុម័តទេ។')}</p>`:''}</section>`;
}
function purchaseBreakdown(p){return p.fuelBreakdown?fuelSummary(p.fuelBreakdown,true):`<section class="card section-body"><p class="warning">${L('Fuel type unavailable · older purchase','មិនមានប្រភេទប្រេង · ការទិញចាស់')}</p>${summary([[L('Saved quantity','បរិមាណរក្សាទុក'),lit(p.quantity)],[L('Saved price (KHR/L)','តម្លៃរក្សាទុក (KHR/លីត្រ)'),Number.isFinite(p.price)?n(p.price):L('Unavailable','មិនមាន')],[L('Saved calculated cost','ថ្លៃគណនារក្សាទុក'),money(p.cost)]])}<p class="sub">${L('Original values retained; no fuel type or new price has been assumed.','រក្សាតម្លៃដើម មិនសន្មតប្រភេទប្រេង ឬតម្លៃថ្មីទេ។')}</p></section>`;}
function purchaseCaption(p){return p.fuelBreakdown?p.fuelBreakdown.lines.filter(x=>x.litres>0).map(x=>fuelName(x.type)+' · '+lit(x.litres)+' × '+n(x.price)+' KHR/L · '+money(x.cost)).join('<br>'):L('Fuel type unavailable · saved legacy total','មិនមានប្រភេទប្រេង · សរុបចាស់បានរក្សាទុក');}

const seed=()=>({version:1,planVersion:1,plan:[{truck:trucks[0].id,runs:[{route:0,litres:20},{route:1,litres:15},{route:2,litres:25}]},{truck:trucks[1].id,runs:[{route:0,litres:20},{route:1,litres:15}]}],days:{},purchases:[]});
let db=seed();try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(parsed.version!==1||!Array.isArray(parsed.plan)||!parsed.days||!Array.isArray(parsed.purchases))throw Error();db=parsed;}}catch(_){loadError=true;}
// Legacy rows are interpreted without rewriting historical purchase snapshots.
function runsFor(r){if(!r)return [];if(Array.isArray(r.runs))return r.runs.map(x=>({...x}));return Array.from({length:Math.max(0,Number(r.count)||0)},()=>({route:Number(r.route),litres:r.allowance}));}
function truckLitres(r){return runsFor(r).reduce((v,x)=>v+Number(x.litres),0);}
function savedRow(r){return {truck:r.truck,runs:runsFor(r).map(x=>({route:Number(x.route),litres:Number(x.litres)}))};}
const total=rows=>rows.reduce((a,r)=>a+truckLitres(r),0),truckFor=r=>trucks.find(t=>t.id===r.truck),routeFor=r=>r.routeName||trucks[r.route]?.route||['Unavailable','មិនមាន'],normal=d=>total(d.rows),approved=d=>d.adjustments.filter(a=>a.status==='approved'),quantity=d=>normal(d)+approved(d).reduce((a,b)=>a+b.delta,0),pending=d=>d.adjustments.filter(a=>a.status==='pending'),purchaseFor=d=>db.purchases.find(p=>p.day===d);
function current(){return db.days[day]||{day,rows:structuredClone(db.plan),planVersion:db.planVersion,adjustments:[],preparedAt:null};}
function effectiveRows(d){const purchase=d.day&&purchaseFor(d.day);if(purchase){const saved=purchase.approvedRows||effectiveRows({rows:purchase.rows||[],adjustments:purchase.adjustments||[]});return structuredClone(saved).map(r=>purchase.fuelBreakdown?r:{...r,fuelType:null,legacyFuel:true});}const rows=structuredClone(d.rows);for(const a of approved(d)){const i=rows.findIndex(r=>r.truck===a.truck);if(a.operation==='remove'){if(i>=0)rows.splice(i,1);}else if(i>=0)rows[i]={...rows[i],...a.after};else if(a.operation==='add')rows.push({...a.after});}return rows;}
function canChange(d=current()){return day===localDate()&&!!d.preparedAt&&!purchaseFor(day)&&role!=='entry';}
function candidates(d=current()){return trucks.filter(t=>!effectiveRows(d).some(r=>r.truck===t.id)&&!pending(d).some(a=>a.truck===t.id));}
function sameRow(a,b){return !!a&&!!b&&a.truck===b.truck&&JSON.stringify(savedRow(a).runs)===JSON.stringify(savedRow(b).runs);}
function freshDay(next){const d=next.days[day];if(day!==localDate()||!d?.preparedAt||next.purchases.some(p=>p.day===day))throw Error();return d;}
function checkBase(d,a){const r=effectiveRows(d).find(r=>r.truck===a.truck);if(a.operation==='add'?!!r:!sameRow(r,a.before))throw Error();}
function dailyRows(d){const rows=effectiveRows(d);for(const a of pending(d))if(a.operation==='add'&&!rows.some(r=>r.truck===a.truck))rows.push({...a.after});return rows;}
function trash(action,truck){const label=action==='remove-plan'?L('Remove from usual plan','ដកចេញពីផែនការធម្មតា'):L('Remove from today','ដកចេញពីថ្ងៃនេះ');return button(action,'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg>','icon danger-text',`data-truck="${E(truck)}" aria-label="${label}: ${E(truck)}" title="${label}"`);}
function truckState(d,r){const a=pending(d).find(a=>a.truck===r.truck),effective=effectiveRows(d).find(x=>x.truck===r.truck);return {a,litres:effective?truckLitres(effective):0,count:effective?runsFor(effective).length:0,label:a?(a.operation==='remove'?L('Removal awaiting approval','ការដកចេញរង់ចាំអនុម័ត'):a.operation==='add'?L('Addition awaiting approval','ការបន្ថែមរង់ចាំអនុម័ត'):stateLabel('pending')):L('No pending changes','គ្មានការកែប្រែរង់ចាំ')};}
function truckActions(d,r,a){if(a)return button('adjustment',L('View request','មើលសំណើ'),'','data-id="'+E(a.id)+'"');return canChange(d)?`<div class="truck-action-row">${button('adjust',L('Adjust','កែសម្រួល'),'','data-truck="'+E(r.truck)+'"')}${trash('remove-today',r.truck)}</div>`:button('truck-detail',L('View details','មើលព័ត៌មាន'),'','data-truck="'+E(r.truck)+'"');}
function truckTable(d){const rows=dailyRows(d);if(!rows.length)return '';return `<div class="daily-truck-table"><table><thead><tr><th scope="col">${L('Truck','រថយន្ត')}</th><th scope="col">${L('Fuel type','ប្រភេទប្រេង')}</th><th scope="col">${L('Planned dispatches','ដំណើរគ្រោងទុក')}</th><th scope="col">${L('Approved litres','លីត្របានអនុម័ត')}</th><th scope="col">${L('Status','ស្ថានភាព')}</th><th scope="col">${L('Actions','សកម្មភាព')}</th></tr></thead><tbody>${rows.map(r=>{const x=truckState(d,r);return `<tr><th scope="row">${E(r.truck)}</th><td>${fuelLabel(r)}</td><td>${n(x.count)}</td><td class="od-nowrap"><strong>${lit(x.litres)}</strong></td><td><span class="badge ${x.a?'pending':''}">${x.label}</span></td><td>${truckActions(d,r,x.a)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function truckList(d){const rows=dailyRows(d);return rows.length?`<div class="truck-list">${rows.map(r=>{const x=truckState(d,r);return `<article class="truck-card"><div class="truck-heading od-row"><strong>${E(r.truck)}</strong><div class="od-field end"><strong class="truck-total">${lit(x.litres)}</strong><span class="sub">${L('Approved litres','លីត្របានអនុម័ត')}</span></div></div><p>${fuelLabel(r)}</p><p class="sub">${n(x.count)} ${L('planned dispatches','ដំណើរគ្រោងទុក')}</p><span class="badge ${x.a?'pending':''}">${x.label}</span><div class="truck-actions">${truckActions(d,r,x.a)}</div></article>`;}).join('')}</div>`:empty(L('No trucks included','មិនមានរថយន្តបានបញ្ចូល'),L('Add an existing truck for today. The usual plan remains unchanged.','បន្ថែមរថយន្តដែលមានសម្រាប់ថ្ងៃនេះ។ ផែនការធម្មតាមិនផ្លាស់ប្តូរ។'));}
function rowDescription(r){return `${fuelName(fuelOf(r))} · ${n(runsFor(r).length)} ${L('planned dispatches','ដំណើរគ្រោងទុក')} · ${lit(truckLitres(r))}`;}
function runBreakdown(r){const runs=runsFor(r);return `<p>${fuelLabel(r)}</p>`+(runs.length?`<ol class="run-breakdown">${runs.map((x,i)=>`<li><div class="od-field"><strong>${L('Dispatch','ដំណើរ')} ${n(i+1)}</strong><span>${E(L(...routeFor(x)))}</span></div><strong class="od-nowrap">${lit(x.litres)}</strong></li>`).join('')}</ol><p class="run-total">${L('Truck total','សរុបរថយន្ត')}: <strong>${lit(truckLitres(r))}</strong></p>`:`<p class="muted">${L('No planned dispatches · 0 L','គ្មានដំណើរគ្រោងទុក · ០ លីត្រ')}</p>`);}
function runEditor(){return `<div class="od-field"><span class="sub">${L('Fuel type · from truck record','ប្រភេទប្រេង · ពីកំណត់ត្រារថយន្ត')}</span>${fuelLabel({truck:draft.truck})}</div><div class="od-stack"><h3>${L('Planned dispatches','ដំណើរគ្រោងទុក')}</h3>${draft.runs.map((r,i)=>`<fieldset class="run-editor"><legend>${L('Dispatch','ដំណើរ')} ${n(i+1)}</legend><div class="run-fields"><label class="od-field">${L('Route','ផ្លូវ')}<select data-run="${i}" data-field="route">${options(trucks.map((t,k)=>[k,L(...t.route)]),r.route)}</select></label><label class="od-field">${L('Required litres','លីត្រត្រូវការ')}<input type="number" data-run="${i}" data-field="litres" min="0" step="any" required value="${E(r.litres)}" aria-describedby="run-error-${i}"><span class="error" id="run-error-${i}"></span></label></div>${button('remove-run',L('Remove dispatch','ដកដំណើរចេញ'),'danger-text',`data-index="${i}" aria-label="${L('Remove dispatch','ដកដំណើរចេញ')} ${n(i+1)}"`)}</fieldset>`).join('')}${!draft.runs.length?`<p>${L('Add a planned dispatch to continue.','បន្ថែមដំណើរគ្រោងទុកដើម្បីបន្ត។')}</p>`:''}${button('add-run',L('Add dispatch','បន្ថែមដំណើរ'))}</div>`;}
function totalsView(d){const req=pending(d).reduce((v,a)=>v+a.delta,0);return `<div class="metrics"><div class="od-stat"><span>${L('Normal required litres','លីត្រត្រូវការធម្មតា')}</span><strong>${lit(normal(d))}</strong></div><div class="od-stat"><span>${L('Pending changes','ការកែប្រែរង់ចាំ')}</span><strong>${req>0?'+':''}${lit(req)}</strong><small>${n(pending(d).length)} ${L('requests','សំណើ')}</small></div><div class="od-stat"><span>${L('Proposed total','សរុបដែលបានស្នើ')}</span><strong>${lit(quantity(d)+req)}</strong></div><div class="od-stat approved"><span>${L('Approved purchase quantity','បរិមាណទិញបានអនុម័ត')}</span><strong>${lit(quantity(d))}</strong></div></div>`;}
const info='<svg width="20" height="20" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/></svg>';
function button(a,t,cls='',extra=''){return `<button type="button" data-act="${a}" class="${cls}" ${extra}>${t}</button>`;}
function screenLink(file,review=''){const q=new URLSearchParams({date:day,lang,tab:approvalScreen?'today':tab});if(params.get('scenario'))q.set('scenario',params.get('scenario'));if(review)q.set('review',review);return file+'?'+q.toString();}
function approvalView(){const d=current();if(!d.preparedAt)return dateControl()+empty(L('No prepared procurement','មិនមានការទិញបានរៀបចំ'),L('Staff prepare today’s procurement before requesting changes.','បុគ្គលិករៀបចំការទិញថ្ងៃនេះ មុនស្នើការកែប្រែ។'),`<a class="button" href="${screenLink('fuel-procurement.html')}">${L('Open fuel preparation','បើកការរៀបចំប្រេង')}</a>`);const items=d.adjustments.filter(a=>approvalFilter==='all'||a.status===approvalFilter);return `${dateControl()}<div class="metrics"><div class="od-stat"><span>${L('Normal requirement','តម្រូវការធម្មតា')}</span><strong>${lit(normal(d))}</strong></div><div class="od-stat"><span>${L('Pending requests','សំណើរង់ចាំ')}</span><strong>${n(pending(d).length)}</strong></div><div class="od-stat"><span>${L('Approved adjustment','ការកែសម្រួលបានអនុម័ត')}</span><strong>${lit(quantity(d)-normal(d))}</strong></div><div class="od-stat approved"><span>${L('Approved purchase quantity','បរិមាណទិញបានអនុម័ត')}</span><strong>${lit(quantity(d))}</strong></div></div>${purchaseFor(day)?purchaseBreakdown(purchaseFor(day)):fuelSummary(dayBreakdown(d))}<section class="card"><div class="section-head od-row"><h2>${L('Adjustment requests','សំណើកែសម្រួល')}</h2>${canChange(d)?button('ed-trucks',L('Manage today’s trucks','គ្រប់គ្រងរថយន្តថ្ងៃនេះ')):''}</div><div class="section-body approval-filters od-cluster" role="group" aria-label="${L('Request status','ស្ថានភាពសំណើ')}">${['pending','approved','rejected','all'].map(v=>button('approval-filter',v==='all'?L('All','ទាំងអស់'):stateLabel(v),v===approvalFilter?'primary':'',`data-filter="${v}" aria-pressed="${v===approvalFilter}"`)).join('')}</div>${items.length?items.map(a=>`<button class="adjust-row" data-act="adjustment" data-id="${E(a.id)}"><span class="od-field"><strong>${E(a.truck)} · ${E(reasonText(a.reason))}</strong><span class="sub">${E(day)} · ${rowDescription(a.after)}</span><span class="sub">${a.initiator==='ed'?L('ED initiated','នាយកប្រតិបត្តិផ្តួចផ្តើម'):L('Requested by General Admin','ស្នើដោយរដ្ឋបាលទូទៅ')}</span></span><span class="od-field end"><strong>${a.delta>0?'+':''}${lit(a.delta)}</strong><span class="badge ${a.status}">${stateLabel(a.status)}</span></span></button>`).join(''):empty(L('No matching requests','មិនមានសំណើត្រូវគ្នា'),L('Requests for this operating day appear here after staff submit them. Change the day or status to view other requests.','សំណើសម្រាប់ថ្ងៃប្រតិបត្តិការនេះបង្ហាញនៅទីនេះ បន្ទាប់ពីបុគ្គលិកដាក់ស្នើ។ ប្តូរថ្ងៃឬស្ថានភាព ដើម្បីមើលសំណើផ្សេង។'))}</section><a class="button" href="${screenLink('fuel-procurement.html')}">${L('Back to fuel preparation','ត្រឡប់ទៅការរៀបចំប្រេង')}</a>`;}
function nav(){return `<nav aria-label="${L('Navigation','ម៉ឺនុយ')}"><p class="eyebrow">${L('HOME','ទំព័រដើម')}</p><a href="home.html?lang=${lang}">${L('Home','ទំព័រដើម')}</a><p class="eyebrow">${L('SALES','ការលក់')}</p><a href="index.html?lang=${lang}">${L('Walk-in sales','ការលក់ផ្ទាល់')}</a><a href="driver-sales.html?lang=${lang}">${L('Driver sales','ការលក់តាមអ្នកបើកបរ')}</a><a href="debt-collection.html?lang=${lang}">${L('Debt collection','ការប្រមូលបំណុល')}</a><p class="eyebrow">${L('OPERATIONS','ប្រតិបត្តិការ')}</p><a href="dispatch-planning.html?lang=${lang}">${L('Dispatch planning','រៀបចំដំណើរ')}</a><a href="${screenLink('fuel-procurement.html')}" ${!approvalScreen?'aria-current="page"':''}>${L('Fuel procurement','ការទិញប្រេងឥន្ធនៈ')}</a><a href="${screenLink('fuel-approvals.html')}" ${approvalScreen?'aria-current="page"':''}>${L('Fuel approvals','ការអនុម័តប្រេង')}</a><p class="eyebrow">${L('FINANCE','ហិរញ្ញវត្ថុ')}</p><a href="daily-finance.html?lang=${lang}">${L('Daily Finance','ហិរញ្ញវត្ថុប្រចាំថ្ងៃ')}</a><p class="eyebrow">${L('REPORTING','របាយការណ៍')}</p><a href="executive-overview.html?lang=${lang}">${L('Executive overview','ទិដ្ឋភាពទូទៅសម្រាប់ថ្នាក់ដឹកនាំ')}</a></nav>`;}
function stateLabel(s){return s==='pending'?L('Awaiting approval','រង់ចាំការអនុម័ត'):s==='approved'?L('Approved','បានអនុម័ត'):L('Rejected','បានបដិសេធ');}
function rowTable(rows,edit=false){return `<div class="usual-trucks">${rows.map(r=>`<article class="usual-truck od-row"><div class="od-field od-fill"><strong>${E(r.truck)}</strong><span class="sub">${rowDescription(r)}</span></div>${edit?`<div class="truck-action-row">${button('edit-plan',L('Edit','កែប្រែ'),'','data-truck="'+E(r.truck)+'"')}${trash('remove-plan',r.truck)}</div>`:''}</article>`).join('')}</div>`;}
function empty(title,body,action=''){return `<div class="empty"><h2>${title}</h2><p>${body}</p>${action}</div>`;}
function render(){const url=new URL(location.href);url.searchParams.set('date',day);url.searchParams.set('lang',lang);url.searchParams.set('tab',tab);history.replaceState(null,'',url);document.documentElement.lang=lang;document.title=approvalScreen?L('Fuel approvals · Sok Heng','ការអនុម័តប្រេង · សុខ ហេង'):L('Fuel procurement · Sok Heng','ការទិញប្រេងឥន្ធនៈ · សុខ ហេង');$('app').innerHTML=`<header class="header"><div class="od-row">${button('menu','☰','mobile-menu',`aria-label="${L('Open navigation','បើកម៉ឺនុយ')}"`)}<strong>${L('SOK HENG','សុខ ហេង')}</strong><span class="muted brand-caption">${L('Ice factory','រោងចក្រទឹកកក')}</span></div><div class="od-row"><span class="session-name">${role==='ed'?L('Executive Director','នាយកប្រតិបត្តិ'):role==='entry'?L('Data Entry','អ្នកបញ្ចូលទិន្នន័យ'):L('General Admin','រដ្ឋបាលទូទៅ')}</span>${role==='entry'?button('staff-view',L('Return to staff view','ត្រឡប់ទៅទិដ្ឋភាពបុគ្គលិក')):''}${button('language',lang==='en'?'ខ្មែរ':'English','','lang="'+(lang==='en'?'km':'en')+'"')}</div></header><div class="layout"><aside>${nav()}</aside><main><div class="heading od-row"><div><p class="eyebrow">${L('OPERATIONS','ប្រតិបត្តិការ')}</p><h1>${approvalScreen?L('Fuel approvals','ការអនុម័តប្រេង'):L('Fuel procurement','ការទិញប្រេងឥន្ធនៈ')}</h1></div>${button('help',info,'icon',`aria-label="${L('About fuel procurement','អំពីការទិញប្រេងឥន្ធនៈ')}"`)}</div><p class="sample">${L('Sample data · Logistics truck types and Settings prices','ទិន្នន័យគំរូ · ប្រភេទប្រេងរថយន្ត និងតម្លៃពីការកំណត់')}</p>${approvalScreen?'':`<div class="tabs" role="tablist">${[['today',L('Daily fuel','ប្រេងប្រចាំថ្ងៃ')],['history',L('Purchase history','ប្រវត្តិទិញ')]].map(([v,t])=>button('tab',t,tab===v?'active':'',`role="tab" aria-selected="${tab===v}" data-tab="${v}"`)).join('')}</div>`}<div id="notice" role="status">${notice?`<p class="notice">${E(notice)}</p>`:''}</div><section id="content">${loadError?empty(L('Could not load fuel records','មិនអាចផ្ទុកកំណត់ត្រាប្រេងបាន'),L('Saved data has not been overwritten. Retry loading.','ទិន្នន័យដែលបានរក្សាទុកមិនត្រូវបានសរសេរជាន់។ សូមសាកល្បងម្តងទៀត។'),button('retry-load',L('Retry','សាកល្បងម្តងទៀត'))):approvalScreen?approvalView():tab==='history'?historyView():todayView()}</section></main></div>`;}
function dateControl(){return `<div class="toolbar od-cluster"><label class="od-field">${L('Operating day','ថ្ងៃប្រតិបត្តិការ')}<input type="date" id="operating-day" value="${E(day)}" max="${localDate()}" required></label>${button('today',L('Today','ថ្ងៃនេះ'))}${current().preparedAt?`<span class="badge approved">${L('Prepared','បានរៀបចំ')}</span>`:''}${!approvalScreen&&role==='ga'?button('manage-plan',L('Manage usual plan','គ្រប់គ្រងផែនការធម្មតា'),'manage-plan'):''}</div>`;}


function procurementSnapshot(d){const b=dayBreakdown(d);return {id:id(),reference:'FUEL-'+day.replaceAll('-','')+'-'+id().slice(0,4).toUpperCase(),day,normal:normal(d),quantity:quantity(d),fuelBreakdown:structuredClone(b),priceVersion:fuelSettings.version,cost:b.cost,rows:structuredClone(d.rows),approvedRows:effectiveRows(d).map(frozenRow),adjustments:structuredClone(approved(d)),createdAt:stamp(),recorder:role};}
function issueAllowed(d){return !approvalScreen&&d.preparedAt&&day===localDate()&&!pending(d).length&&quantity(d)>0&&dayBreakdown(d).complete&&!purchaseFor(day);}
function ticket(p,issued=false){return `<article class="procurement-ticket" lang="${lang}"><header><strong>${L('SOK HENG','សុខ ហេង')}</strong><h3>${L('Fuel procurement ticket','ប័ណ្ណទិញប្រេងឥន្ធនៈ')}</h3>${issued?`<p>${L('Issued','បានចេញប័ណ្ណ')}</p>`:''}</header><div class="ticket-meta"><p>${L('Reference','លេខយោង')}: <strong>${E(p.reference)}</strong></p><p>${L('Operating day','ថ្ងៃប្រតិបត្តិការ')}: <strong>${E(p.day)}</strong></p></div>${p.fuelBreakdown?`<table><thead><tr><th>${L('Fuel type','ប្រភេទប្រេង')}</th><th>${L('Litres','លីត្រ')}</th><th>${L('Price (KHR/L)','តម្លៃ (KHR/លីត្រ)')}</th><th>${L('Cost (KHR)','ថ្លៃ (KHR)')}</th></tr></thead><tbody>${p.fuelBreakdown.lines.map(x=>`<tr><th scope="row">${fuelName(x.type)}</th><td>${n(x.litres)}</td><td>${Number.isFinite(x.price)&&x.price>0?n(x.price):L('Price needed','ត្រូវការតម្លៃ')}</td><td>${x.cost===null?'—':n(x.cost)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="3">${L('Total calculated cost','ថ្លៃគណនាសរុប')}</th><td>${p.fuelBreakdown.complete?money(p.cost):L('Incomplete','មិនពេញលេញ')}</td></tr></tfoot></table>${p.fuelBreakdown.unknown?`<p class="error">${L('Fuel type needed','ត្រូវការប្រភេទប្រេង')}: ${lit(p.fuelBreakdown.unknown)}</p>`:''}`:purchaseBreakdown(p)}</article>`;}
function dailyFuelSummary(d,p){const content=p?purchaseBreakdown(p):fuelSummary(dayBreakdown(d));const action=p?button('purchase-detail',L('View / Print ticket','មើល / បោះពុម្ពប័ណ្ណ'),'','data-id="'+E(p.id)+'"'):day===localDate()?button('review-purchase',L('Issue procurement','ចេញប័ណ្ណទិញប្រេង'),'primary'):'';return content.replace(/<\/section>$/,`<div class="fuel-issue-footer">${p?`<span class="badge approved">${L('Completed','បានបញ្ចប់')}</span>`:''}${action}</div></section>`);}

function todayView(){const d=current(),p=purchaseFor(day);if(!d.preparedAt){if(day!==localDate())return dateControl()+empty(L('No saved procurement','មិនមានការរៀបចំបានរក្សាទុក'),L('Preparation is available for today only. Select Today to prepare procurement.','អាចរៀបចំបានតែថ្ងៃនេះប៉ុណ្ណោះ។ ជ្រើសថ្ងៃនេះដើម្បីរៀបចំ។'));return `${dateControl()}<section class="card prepare-card"><h2>${L('Prepare today’s procurement','រៀបចំការទិញសម្រាប់ថ្ងៃនេះ')}</h2><p class="muted">${n(db.plan.length)} ${L('trucks in the usual plan','រថយន្តក្នុងផែនការធម្មតា')}</p><strong class="cost">${lit(total(db.plan))}</strong><p class="muted">${L('Start with the usual plan, then manage today’s trucks.','ចាប់ផ្តើមពីផែនការធម្មតា រួចគ្រប់គ្រងរថយន្តថ្ងៃនេះ។')}</p>${role==='ga'?button('prepare',busy?L('Preparing…','កំពុងរៀបចំ…'):L('Prepare procurement','រៀបចំការទិញ'),'primary',busy||!db.plan.length?'disabled':''):''}</section>`;}
return `${dateControl()}${d.planVersion!==db.planVersion?`<p class="sub snapshot-note">${L('The usual plan has changed. This prepared day keeps its original plan.','ផែនការធម្មតាបានផ្លាស់ប្តូរ។ ថ្ងៃដែលរៀបចំរួចរក្សាផែនការដើម។')}</p>`:''}${totalsView(d)}<section class="card today-trucks"><div class="section-head od-row"><h2>${L('Today’s trucks','រថយន្តថ្ងៃនេះ')}</h2>${canChange(d)?button('add-today',L('Add truck','បន្ថែមរថយន្ត'),'',candidates(d).length?'':'disabled'):''}</div>${truckTable(d)}${truckList(d)}</section>${dailyFuelSummary(d,p)}${d.adjustments.length?`<details class="card"><summary class="section-head">${L('Adjustment history','ប្រវត្តិកែសម្រួល')} · ${n(d.adjustments.length)}</summary>${d.adjustments.map(a=>`<button class="adjust-row" data-act="adjustment" data-id="${E(a.id)}"><span class="od-field"><strong>${E(a.truck)} · ${E(reasonText(a.reason))}</strong><span class="sub">${a.delta>0?'+':''}${lit(a.delta)}</span></span><span class="badge ${a.status}">${stateLabel(a.status)}</span></button>`).join('')}</details>`:''}`;}

function planView(){return `<div class="toolbar od-row"><div><h2>${L('Usual daily fuel plan','ផែនការប្រេងប្រចាំថ្ងៃធម្មតា')}</h2><p class="muted">${L('Changes apply to future preparations. Prepared days keep their saved truck list.','ការកែប្រែអនុវត្តចំពោះការរៀបចំបន្ទាប់។ ថ្ងៃរៀបចំរួចរក្សាបញ្ជីរថយន្តដើម។')}</p></div>${role==='ga'?button('add-plan',L('Add truck','បន្ថែមរថយន្ត'),'primary',db.plan.length>=trucks.length?'disabled':''):''}</div><section class="card">${db.plan.length?rowTable(db.plan,role==='ga'):empty(L('No assignments yet','មិនទាន់មានការចាត់តាំង'),L('Select existing trucks and routes to establish the usual plan.','ជ្រើសរថយន្តនិងផ្លូវដែលមាន ដើម្បីបង្កើតផែនការធម្មតា។'))}<div class="section-head od-row"><strong>${L('Total daily requirement','តម្រូវការប្រចាំថ្ងៃសរុប')}</strong><strong class="cost">${lit(total(db.plan))}</strong></div></section><p class="muted">${L('Calculated by adding each planned dispatch’s litres. Actual dispatch records are not required.','គណនាដោយបូកលីត្រនៃដំណើរគ្រោងទុកនីមួយៗ។ មិនទាមទារកំណត់ត្រាដំណើរជាក់ស្តែងទេ។')}</p>`;}
function historyView(){const rows=[...db.purchases].sort((a,b)=>b.day.localeCompare(a.day)),pages=Math.max(1,Math.ceil(rows.length/8));historyPage=Math.min(historyPage,pages);return `<div class="toolbar"><h2>${L('Recorded purchases','ការទិញដែលបានកត់ត្រា')}</h2><p class="muted">${L('Saved quantities and prices are retained. These are not payment records.','រក្សាបរិមាណនិងតម្លៃដែលបានកត់ត្រា។ ទាំងនេះមិនមែនជាកំណត់ត្រាទូទាត់ទេ។')}</p></div><section class="card">${rows.length?rows.slice((historyPage-1)*8,historyPage*8).map(p=>`<button data-act="purchase-detail" data-id="${p.id}" class="adjust-row"><span class="od-field"><strong>${E(p.day)}</strong><span class="sub">${E(p.reference)}</span></span><span class="od-field end"><strong>${money(p.cost)}</strong><span class="sub">${lit(p.quantity)} · ${purchaseCaption(p)}</span></span></button>`).join(''):empty(L('No recorded purchases','មិនមានការទិញបានកត់ត្រា'),L('Recorded purchases will appear here with their original price and approval details.','ការទិញដែលបានកត់ត្រានឹងបង្ហាញនៅទីនេះ ជាមួយតម្លៃដើមនិងព័ត៌មានអនុម័ត។'))}</section>${rows.length?`<div class="pager od-row">${button('previous',L('Previous','មុន'),' ',historyPage===1?'disabled':'')}<span>${n(historyPage)} / ${n(pages)}</span>${button('next',L('Next','បន្ទាប់'),' ',historyPage===pages?'disabled':'')}</div>`:''}`;}
function reasonText(v){return ({runs:L('Planned dispatch changes','កែប្រែដំណើរគ្រោងទុក'),add:L('Add truck','បន្ថែមរថយន្ត'),remove:L('Remove from today','ដកចេញពីថ្ងៃនេះ'),extra:L('Extra dispatch','ដំណើរបន្ថែម'),unavailable:L('Truck unavailable','រថយន្តមិនអាចប្រើបាន'),route:L('Route change','ប្តូរផ្លូវ')})[v]||v;}
function field(label,name,value,type='number',extra=''){return `<label class="od-field">${label}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;}
function options(items,value){return items.map(([v,t])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(t)}</option>`).join('');}
function summary(rows){return `<dl class="summary">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;}
function errorBox(){return '<p id="form-error" class="error" role="alert" tabindex="-1"></p>';}
function open(type,data={}){modal={type,...data};draft=structuredClone(data.draft||{});if(type==='review')modal.ticket=procurementSnapshot(current());if(type==='plan'||type==='adjust')draft.runs=runsFor(draft);drawModal();if(!$('dialog').open)$('dialog').showModal();}
function drawModal(){const d=current();let title='',body='',footer='',small=false;const submit=t=>`<button type="submit" class="primary" ${busy?'disabled':''}>${busy?L('Saving…','កំពុងរក្សាទុក…'):t}</button>`;
if(modal.type==='ed-trucks'){title=L('Today’s trucks','រថយន្តថ្ងៃនេះ');body=truckList(d);footer=canChange(d)?button('add-today',L('Add truck','បន្ថែមរថយន្ត'),'',candidates(d).length?'':'disabled'):'';}
if(modal.type==='manage'){title=L('Manage usual plan','គ្រប់គ្រងផែនការធម្មតា');body=planView();}
if(modal.type==='remove-plan'||modal.type==='remove-today'){const recurring=modal.type==='remove-plan';title=recurring?L('Remove from usual plan','ដកចេញពីផែនការធម្មតា'):L('Remove from today','ដកចេញពីថ្ងៃនេះ');body=`<strong>${E(modal.truck)}</strong><p>${recurring?L('Remove this truck from future preparations? Prepared days will keep their saved trucks.','ដករថយន្តនេះពីការរៀបចំបន្ទាប់? ថ្ងៃរៀបចំរួចរក្សារថយន្តដើម។'):L('Exclude this truck from today only? The usual plan stays unchanged.','ដករថយន្តនេះចេញតែថ្ងៃនេះ? ផែនការធម្មតាមិនផ្លាស់ប្តូរ។')}</p>${!recurring?summary([[L('Current truck litres','លីត្ររថយន្តបច្ចុប្បន្ន'),lit(truckLitres(modal.before))],[L('Proposed truck litres','លីត្ររថយន្តបានស្នើ'),lit(0)]])+`<p>${role==='ed'?L('This ED change takes effect directly.','ការកែប្រែរបស់នាយកមានប្រសិទ្ធភាពភ្លាម។'):L('The truck stays included until ED approval.','រថយន្តនៅតែបានបញ្ចូលរហូតដល់នាយកអនុម័ត។')}</p>`:''}${errorBox()}`;footer=button(recurring?'manage-plan':'close',L('Cancel','បោះបង់'))+submit(recurring?L('Remove from usual plan','ដកចេញពីផែនការធម្មតា'):role==='ed'?L('Remove from today','ដកចេញពីថ្ងៃនេះ'):L('Request removal','ស្នើដកចេញ'));}
if(modal.type==='truck-detail'){const r=effectiveRows(d).find(x=>x.truck===modal.truck);title=L('Planned dispatches','ដំណើរគ្រោងទុក');body=r?`<strong>${E(r.truck)}</strong>${runBreakdown(r)}`:L('Record unavailable','មិនមានកំណត់ត្រា');}
if(modal.type==='menu'){title=L('Navigation','ម៉ឺនុយ');body=nav();}
if(modal.type==='help'){small=true;title=L('How fuel procurement works','របៀបដំណើរការការទិញប្រេង');body=`<p>${L('The usual plan uses Logistics assignments before actual dispatches exist. Temporary changes apply only to the selected day. Pending or rejected requests do not affect approved litres.','ផែនការធម្មតាប្រើការចាត់តាំងដឹកជញ្ជូន មុនមានដំណើរជាក់ស្តែង។ ការកែសម្រួលបណ្តោះអាសន្នអនុវត្តតែថ្ងៃដែលជ្រើស។ សំណើរង់ចាំឬបដិសេធមិនប៉ះពាល់លីត្រដែលបានអនុម័តទេ។')}</p><p>${L('Calculated cost is not money paid. The event linking a purchase to a paid expense is still to be agreed. No finance entry is created here.','ថ្លៃគណនាមិនមែនប្រាក់បានចំណាយទេ។ ពេលភ្ជាប់ការទិញទៅចំណាយដែលបានទូទាត់នៅតែត្រូវព្រមព្រៀង។ មិនបង្កើតកំណត់ត្រាហិរញ្ញវត្ថុនៅទីនេះទេ។')}</p><p>${L('Precision, no-purchase days, pending requests at recording, corrections and changes to prepared plans remain under review.','ភាពជាក់លាក់ ថ្ងៃមិនទិញ សំណើរង់ចាំពេលកត់ត្រា ការកែតម្រូវ និងការប្តូរផែនការបានរៀបចំ កំពុងរង់ចាំពិនិត្យ។')}</p>`;}
if(modal.type==='plan'){title=modal.truck?L('Edit usual assignment','កែការចាត់តាំងធម្មតា'):L('Add usual assignment','បន្ថែមការចាត់តាំងធម្មតា');body=`<p>${L('This changes the usual plan for future preparation.','នេះប្តូរផែនការធម្មតាសម្រាប់ការរៀបចំបន្ទាប់។')}</p><label class="od-field">${L('Existing truck','រថយន្តដែលមាន')}<select name="truck" ${modal.truck?'disabled':''}>${options(trucks.filter(t=>modal.truck===t.id||!db.plan.some(r=>r.truck===t.id)).map(t=>[t.id,t.id+' · '+t.plate]),draft.truck)}</select></label>${runEditor()}<div id="live-total" class="calculation"></div>${errorBox()}`;footer=button('manage-plan',L('Back to usual plan','ត្រឡប់ទៅផែនការធម្មតា'))+submit(L('Save usual plan','រក្សាទុកផែនការធម្មតា'));}
if(modal.type==='adjust'){const adding=modal.operation==='add';title=adding?L('Add truck for today','បន្ថែមរថយន្តសម្រាប់ថ្ងៃនេះ'):L('Adjust truck for today','កែសម្រួលរថយន្តសម្រាប់ថ្ងៃនេះ');body=`<p class="muted">${E(day)} · ${L('Today only; usual plan stays unchanged.','សម្រាប់ថ្ងៃនេះតែប៉ុណ្ណោះ ផែនការធម្មតាមិនផ្លាស់ប្តូរ។')}</p>${adding?`<label class="od-field">${L('Existing truck','រថយន្តដែលមាន')}<select name="truck">${options(candidates(d).map(t=>[t.id,t.id+' · '+t.plate]),draft.truck)}</select></label>`:`<strong>${E(draft.truck)}</strong><div class="calculation">${L('Current','បច្ចុប្បន្ន')}: ${rowDescription(modal.before)}</div>`}${runEditor()}<label class="od-field">${L('Reason / notes','មូលហេតុ / កំណត់សម្គាល់')}<textarea name="note" rows="3" maxlength="500">${E(draft.note||'')}</textarea></label><div id="live-total" class="calculation"></div><p class="muted">${role==='ed'?L('Your change takes effect directly; no separate ED approval.','ការកែប្រែរបស់អ្នកមានប្រសិទ្ធភាពភ្លាមៗ មិនត្រូវការអនុម័តដាច់ដោយឡែក។'):L('Approved litres stay unchanged until ED approval.','លីត្របានអនុម័តមិនផ្លាស់ប្តូររហូតដល់នាយកអនុម័ត។')}</p>${errorBox()}`;footer=submit(role==='ed'?L('Apply change','អនុវត្តការកែប្រែ'):L('Send for approval','ផ្ញើសុំអនុម័ត'));}
if(modal.type==='adjustment'){const a=d.adjustments.find(x=>x.id===modal.id);title=L('Adjustment details','ព័ត៌មានការកែសម្រួល');if(!a){body=L('Record unavailable','មិនមានកំណត់ត្រា');}else{body=`<span class="badge ${a.status}">${stateLabel(a.status)}</span>${summary([[L('Operating day','ថ្ងៃប្រតិបត្តិការ'),E(day)],[L('Truck','រថយន្ត'),E(a.truck)],[L('Reason','មូលហេតុ'),E(reasonText(a.reason))],[L('Before','មុន'),rowDescription(a.before)],[L('Requested','បានស្នើ'),rowDescription(a.after)],[L('Adjustment','ការកែសម្រួល'),(a.delta>0?'+':'')+lit(a.delta)],[L('Approved daily quantity','បរិមាណប្រចាំថ្ងៃបានអនុម័ត'),lit(quantity(d))],...(a.status==='pending'?[[L('Daily quantity after approval','បរិមាណប្រចាំថ្ងៃបន្ទាប់ពីអនុម័ត'),lit(quantity(d)+a.delta)]]:[]),[L('Requested at','ពេលស្នើ'),E(new Date(a.createdAt).toLocaleString())],[L('Approval','ការអនុម័ត'),a.status==='approved'?(a.initiator==='ed'?L('ED initiated · separate approval not required','នាយកផ្តួចផ្តើម · មិនត្រូវការអនុម័តដាច់ដោយឡែក'):L('Approved by ED','អនុម័តដោយនាយកប្រតិបត្តិ')):stateLabel(a.status)]])}${a.status==='rejected'?summary([[L('Rejected by','បដិសេធដោយ'),a.rejectedBy==='ed'?L('Executive Director','នាយកប្រតិបត្តិ'):L('Unavailable','មិនមាន')],[L('Rejected at','ពេលបដិសេធ'),a.rejectedAt?E(new Date(a.rejectedAt).toLocaleString()):L('Unavailable','មិនមាន')],[L('Reason for rejection','មូលហេតុបដិសេធ'),E(a.rejectionReason||L('Not provided','មិនបានបញ្ជាក់'))]]):''}<h3>${L('Before','មុន')}</h3>${runBreakdown(a.before)}<h3>${L('Proposed','បានស្នើ')}</h3>${runBreakdown(a.after)}<p>${E(a.note||'')}</p>${a.status==='pending'?`<p class="muted">${L('Revision and resubmission behaviour is awaiting review.','របៀបកែប្រែ និងស្នើឡើងវិញកំពុងរង់ចាំពិនិត្យ។')}</p>`:''}${errorBox()}`;if(a.status==='pending'&&role==='ed'&&canChange(d))footer=button('reject-request',L('Reject','បដិសេធ'),'danger-text',busy?'disabled':'')+submit(L('Approve adjustment','អនុម័តការកែសម្រួល'));else if(a.status==='pending'&&role!=='ed')footer=`<a class="button" href="${screenLink('fuel-approvals.html',a.id)}">${L('Open ED review','បើកការពិនិត្យរបស់នាយក')}</a>`;}}
if(modal.type==='review'){title=L('Issue procurement','ចេញប័ណ្ណទិញប្រេង');const p=modal.ticket;body=ticket(p)+`<p class="sub">${L('Confirm completes this procurement request and saves the ticket values. Printing alone does not confirm it.','បញ្ជាក់ដើម្បីបញ្ចប់សំណើ និងរក្សាទុកតម្លៃប័ណ្ណ។ ការបោះពុម្ពតែឯងមិនមែនជាការបញ្ជាក់ទេ។')}</p>${!p.fuelBreakdown.complete?`<p class="error">${L('Fuel type or required price is missing. Complete the source records before issuing.','ខ្វះប្រភេទប្រេង ឬតម្លៃត្រូវការ។ បំពេញកំណត់ត្រាប្រភពមុនចេញប័ណ្ណ។')}</p>`:''}${pending(d).length?`<p class="warning">${L('Approval is pending. Pending changes are excluded; issuing while requests remain pending awaits a policy decision.','ការអនុម័តកំពុងរង់ចាំ។ ការកែប្រែរង់ចាំមិនបានបញ្ចូល។ ការចេញប័ណ្ណនៅពេលមានសំណើរង់ចាំ ត្រូវការការសម្រេចគោលការណ៍។')}</p>`:''}${quantity(d)<=0?`<p class="warning">${L('No-purchase-day handling remains to be agreed.','របៀបគ្រប់គ្រងថ្ងៃមិនទិញនៅមិនទាន់ព្រមព្រៀង។')}</p>`:''}${errorBox()}`;footer=button('print-ticket',L('Print ticket','បោះពុម្ពប័ណ្ណ'),'',busy?'disabled':'')+(issueAllowed(d)?submit(L('Confirm','បញ្ជាក់')):'');}
if(modal.type==='reject'){const a=d.adjustments.find(x=>x.id===modal.id);small=true;title=L('Reject request?','បដិសេធសំណើ?');body=a?`<p><strong>${E(a.truck)}</strong> · ${fuelName(a.fuelType)} · ${a.delta>0?'+':''}${lit(a.delta)}</p><p>${L('This request will be marked Rejected. Approved litres and the usual plan will remain unchanged.','សំណើនេះនឹងត្រូវបានសម្គាល់ថាបានបដិសេធ។ លីត្របានអនុម័ត និងផែនការធម្មតាមិនផ្លាស់ប្តូរ។')}</p><label>${L('Reason (optional)','មូលហេតុ (មិនចាំបាច់)')}<textarea name="rejectionReason" rows="3" maxlength="500" ${busy?'disabled':''}>${E(draft.rejectionReason||'')}</textarea></label>${errorBox()}`:L('Record unavailable','មិនមានកំណត់ត្រា');if(a?.status==='pending'&&role==='ed'&&canChange(d))footer=button('cancel-rejection',L('Cancel','បោះបង់'),'',busy?'disabled':'')+submit(L('Confirm rejection','បញ្ជាក់ការបដិសេធ'));}
if(modal.type==='purchase'){const p=db.purchases.find(x=>x.id===modal.id);title=L('Procurement ticket','ប័ណ្ណទិញប្រេង');body=p?ticket(p,true)+`<details><summary>${L('Procurement details','ព័ត៌មានការទិញប្រេង')}</summary>${summary([[L('Recorded at','ពេលកត់ត្រា'),E(new Date(p.issuedAt||p.createdAt).toLocaleString())],[L('Recorded quantity','បរិមាណកត់ត្រា'),lit(p.quantity)]])}${(p.approvedRows||effectiveRows({rows:p.rows||[],adjustments:p.adjustments||[]})).map(r=>`<strong>${E(r.truck)}</strong>${runBreakdown(p.fuelBreakdown?r:{...r,fuelType:null,legacyFuel:true})}`).join('')}<h3>${L('Approval history','ប្រវត្តិអនុម័ត')}</h3>${(p.adjustments||[]).map(a=>`<p>${E(a.truck)} · ${stateLabel(a.status)} · ${lit(a.delta)} · ${E(a.approvedAt||'')}</p>`).join('')}</details>`:L('Record unavailable','មិនមានកំណត់ត្រា');if(p)footer=button('print-ticket',L('Print ticket','បោះពុម្ពប័ណ្ណ'));}
$('dialog').className=['review','purchase'].includes(modal.type)?'ticket-dialog':small?'small-dialog':'panel';$('dialog').innerHTML=`<form id="fuel-form" novalidate><header class="panel-head od-row"><h2 id="dialog-title">${title}</h2><div class="od-row">${button('language',lang==='en'?'ខ្មែរ':'English','',busy?'disabled':'')}${button('close',L('Close','បិទ'),'',busy?'disabled':'')}</div></header><div class="panel-body">${body}</div>${footer?`<footer class="panel-footer">${footer}</footer>`:''}</form>`;updateLive();}
function updateLive(){const el=$('live-total');if(!el)return;const val=truckLitres(draft);if(draft.runs.some(r=>r.litres===''||!Number.isFinite(Number(r.litres)))||!Number.isFinite(val)){el.textContent='—';return;}if(modal.type==='plan')el.textContent=L('Daily requirement: ','តម្រូវការប្រចាំថ្ងៃ៖ ')+lit(val);else{const r=effectiveRows(current()).find(x=>x.truck===draft.truck);const delta=val-(r?truckLitres(r):0);el.innerHTML=summary([[L('Fuel type','ប្រភេទប្រេង'),fuelName(fuelOf({truck:draft.truck}))],[L('Truck litres today','លីត្ររថយន្តថ្ងៃនេះ'),lit(val)],[L('Requested adjustment','ការកែសម្រួលស្នើ'),(delta>0?'+':'')+lit(delta)],[L('Quantity if approved','បរិមាណបើបានអនុម័ត'),lit(quantity(current())+delta)]]);}}
function error(msg){const el=$('form-error');if(el){el.textContent=msg;el.focus();}}
async function save(change,message){if(busy)return;const returnToPlan=['plan','remove-plan'].includes(modal?.type);busy=true;if(modal)drawModal();try{await new Promise(r=>setTimeout(r,450));if(failNext){failNext=false;throw Error();}const raw=localStorage.getItem(key);const next=raw?JSON.parse(raw):structuredClone(db);if(next.version!==1||!Array.isArray(next.plan)||!next.days||!Array.isArray(next.purchases))throw Error();change(next);localStorage.setItem(key,JSON.stringify(next));db=next;busy=false;if($('dialog').open)$('dialog').close();modal=null;notice=message;render();if(returnToPlan)open('manage');}catch(err){busy=false;if(err.staleProcurement&&modal?.type==='review'){try{db=JSON.parse(localStorage.getItem(key))||db;}catch(_){}const previous=modal.ticket;modal.ticket={...procurementSnapshot(current()),id:previous.id,reference:previous.reference};render();drawModal();error(L('The procurement changed. Review the updated ticket, then confirm again. Nothing was saved.','ការទិញបានផ្លាស់ប្តូរ។ ពិនិត្យប័ណ្ណថ្មី រួចបញ្ជាក់ម្តងទៀត។ មិនមានការរក្សាទុក។'));return;}if(modal){drawModal();error(L('Could not save. Your entries are retained. Try again.','មិនអាចរក្សាទុកបាន។ ទិន្នន័យរបស់អ្នកនៅដដែល។ សូមសាកល្បងម្តងទៀត។'));}else{notice=L('Could not save. Nothing was changed. Try again.','មិនអាចរក្សាទុកបាន។ មិនមានការផ្លាស់ប្តូរ។ សូមសាកល្បងម្តងទៀត។');render();}}}
function numericValid(){if(!draft.runs?.length){error(L('Add at least one planned dispatch. Use Remove from today to exclude the truck.','បន្ថែមដំណើរគ្រោងទុកយ៉ាងហោចណាស់មួយ។ ប្រើដកចេញពីថ្ងៃនេះដើម្បីដករថយន្ត។'));return false;}for(const [i,r] of draft.runs.entries()){if(!trucks[Number(r.route)]||r.litres===''||!Number.isFinite(Number(r.litres))||Number(r.litres)<=0){error(L('Check dispatch ','ពិនិត្យដំណើរ ')+n(i+1)+L(': select a route and enter positive litres.', '៖ ជ្រើសផ្លូវ និងបញ្ចូលលីត្រវិជ្ជមាន។'));return false;}if(!Number.isInteger(Number(r.litres))){error(L('Fractional-litre precision awaits agreement. Use whole litres in this prototype.','ភាពជាក់លាក់លីត្រទសភាគរង់ចាំព្រមព្រៀង។ ប្រើលីត្រគត់ក្នុងគំរូនេះ។'));return false;}}return true;}
document.addEventListener('submit',e=>{if(e.target.id!=='fuel-form')return;e.preventDefault();if(busy)return;const d=current();if(modal.type==='plan'){if(role!=='ga'||!numericValid())return;const r=savedRow(draft);if(!trucks.some(t=>t.id===r.truck))return error(L('Select an existing truck.','ជ្រើសរថយន្តដែលមាន។'));save(next=>{const i=next.plan.findIndex(x=>x.truck===r.truck);if(i>=0)next.plan[i]=r;else next.plan.push(r);next.planVersion++;},L('Usual plan saved. Prepared days retain their snapshots.','បានរក្សាទុកផែនការធម្មតា។ ថ្ងៃដែលបានរៀបចំរក្សាទិន្នន័យដើម។'));}
else if(modal.type==='remove-plan'){if(role!=='ga')return;const truck=modal.truck;save(next=>{next.plan=next.plan.filter(r=>r.truck!==truck);next.planVersion++;},L('Removed from usual plan. Prepared days are unchanged.','បានដកចេញពីផែនការធម្មតា។ ថ្ងៃរៀបចំរួចមិនផ្លាស់ប្តូរ។'));}
else if(modal.type==='adjust'||modal.type==='remove-today'){if(!canChange(d))return error(L('Only today’s prepared procurement can be changed.','អាចកែប្រែបានតែការរៀបចំថ្ងៃនេះ។'));const removing=modal.type==='remove-today',operation=removing?'remove':modal.operation||'adjust';if(!removing&&!numericValid())return;const truck=removing?modal.truck:draft.truck,before=operation==='add'?{truck,runs:[]}:modal.before;if(!before||pending(d).some(a=>a.truck===truck))return error(L('This truck already has a pending request.','រថយន្តនេះមានសំណើរង់ចាំរួចហើយ។'));const after=removing?{truck,runs:[]}:savedRow(draft),delta=truckLitres(after)-truckLitres(before);if(operation==='adjust'&&sameRow(before,after))return error(L('Change a planned dispatch route or litres, or add/remove a dispatch.','ប្តូរផ្លូវ ចំនួនដំណើរ ឬបរិមាណប្រេង។'));const requestType=fuelOf({truck});before.fuelType=requestType;after.fuelType=requestType;before.runs=runsFor(before).map(r=>({...r,routeName:structuredClone(routeFor(r))}));after.runs=runsFor(after).map(r=>({...r,routeName:structuredClone(routeFor(r))}));const a={id:id(),operation,truck,fuelType:requestType,before,after,delta,reason:operation==='adjust'?'runs':operation,note:draft.note||'',initiator:role,status:role==='ed'?'approved':'pending',createdAt:stamp(),approvedAt:role==='ed'?stamp():null};save(next=>{const record=freshDay(next);if(pending(record).some(x=>x.truck===truck)||!trucks.some(t=>t.id===truck))throw Error();checkBase(record,a);record.adjustments.push(a);},role==='ed'?L('Change applied. Usual plan unchanged.','បានអនុវត្តការកែប្រែ។ ផែនការធម្មតាមិនផ្លាស់ប្តូរ។'):L('Request sent. Approved purchase quantity is unchanged.','បានផ្ញើសំណើ។ បរិមាណទិញបានអនុម័តមិនផ្លាស់ប្តូរ។'));}
else if(modal.type==='reject'&&role==='ed'){if(!canChange(d))return;const aid=modal.id,reason=(draft.rejectionReason||'').trim();save(next=>{const record=freshDay(next),a=record.adjustments.find(x=>x.id===aid);if(!a||a.status!=='pending'||next.purchases.some(p=>p.day===day))throw Error();a.status='rejected';a.rejectedAt=stamp();a.rejectedBy='ed';a.rejectionReason=reason;},L('Request rejected. Approved purchase quantity is unchanged.','បានបដិសេធសំណើ។ បរិមាណទិញបានអនុម័តមិនផ្លាស់ប្តូរ។'));}
else if(modal.type==='adjustment'&&role==='ed'){const aid=modal.id;save(next=>{const record=freshDay(next);const a=record.adjustments.find(x=>x.id===aid);if(!a||a.status!=='pending'||next.purchases.some(p=>p.day===day))throw Error();checkBase(record,a);a.status='approved';a.approvedAt=stamp();},L('Adjustment approved. Purchase quantity updated.','បានអនុម័តការកែសម្រួល។ បរិមាណទិញបានធ្វើបច្ចុប្បន្នភាព។'));}
else if(modal.type==='review'&&issueAllowed(d)){const p=structuredClone(modal.ticket);save(next=>{const record=next.days[day];if(day!==localDate()||!record?.preparedAt||next.purchases.some(x=>x.day===day))throw Error();if(pending(record).length||quantity(record)!==p.quantity||JSON.stringify(effectiveRows(record).map(frozenRow))!==JSON.stringify(p.approvedRows)||JSON.stringify(dayBreakdown(record))!==JSON.stringify(p.fuelBreakdown)){const err=Error();err.staleProcurement=true;throw err;}p.issuedAt=stamp();p.status='issued';next.purchases.push(p);},L('Procurement completed. The ticket is saved and available for printing.','ការទិញប្រេងបានបញ្ចប់។ ប័ណ្ណបានរក្សាទុក និងអាចបោះពុម្ពបាន។'));}});
function updateRun(e){if(e.target.dataset.run===undefined)return false;const r=draft.runs?.[Number(e.target.dataset.run)];if(!r)return false;r[e.target.dataset.field]=e.target.value;updateLive();return true;}
document.addEventListener('input',e=>{if(updateRun(e))return;if(e.target.closest('#fuel-form')&&e.target.name){draft[e.target.name]=e.target.value;updateLive();}});
document.addEventListener('change',e=>{if(updateRun(e))return;if(e.target.id==='operating-day'){if(e.target.value&&e.target.value<=localDate()){day=e.target.value;notice='';render();}}if(e.target.closest('#fuel-form')&&e.target.name){draft[e.target.name]=e.target.value;if(modal.type==='adjust'&&e.target.name==='truck'&&modal.operation==='add'){const r=db.plan.find(r=>r.truck===draft.truck)||{route:trucks.findIndex(t=>t.id===draft.truck),count:1,allowance:''};draft={...draft,runs:runsFor(r)};drawModal();}else if(modal.type==='plan'&&e.target.name==='truck'){drawModal();}else if(modal.type==='adjust'&&e.target.name==='reason'&&draft.reason==='unavailable'){draft.count=0;drawModal();}updateLive();}});
document.addEventListener('focusout',e=>{if(e.target.dataset.field!=='litres')return;const invalid=e.target.value===''||!Number.isFinite(Number(e.target.value))||Number(e.target.value)<=0;e.target.setAttribute('aria-invalid',String(invalid));const el=$('run-error-'+e.target.dataset.run);if(el)el.textContent=invalid?L('Enter positive litres.','បញ្ចូលលីត្រវិជ្ជមាន។'):'';});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||busy)return;const a=b.dataset.act;if(a==='reject-request'){if(role==='ed'&&canChange()&&modal?.type==='adjustment')open('reject',{id:modal.id});return;}if(a==='cancel-rejection'){if(modal?.type==='reject')open('adjustment',{id:modal.id});return;}if(a==='print-ticket'){const paper=$('dialog').querySelector('.procurement-ticket');if(paper){let print=$('fuel-print');if(!print){print=document.createElement('div');print.id='fuel-print';document.body.append(print);}print.innerHTML=paper.outerHTML;document.body.classList.add('printing-fuel');window.print();document.body.classList.remove('printing-fuel');}return;}if(a==='truck-detail'){open('truck-detail',{truck:b.dataset.truck});return;}if(a==='add-run'){draft.runs.push({route:0,litres:''});drawModal();return;}if(a==='remove-run'){draft.runs.splice(Number(b.dataset.index),1);drawModal();return;}if(a==='manage-plan'){if(role==='ga')open('manage');return;}if(a==='ed-trucks'){if(role==='ed')open('ed-trucks');return;}if(a==='remove-plan'){if(role==='ga')open('remove-plan',{truck:b.dataset.truck});return;}if(a==='remove-today'){const r=effectiveRows(current()).find(r=>r.truck===b.dataset.truck);if(canChange()&&r)open('remove-today',{truck:r.truck,before:structuredClone(r)});return;}if(a==='add-today'){if(!canChange())return;const t=candidates()[0];if(!t)return;const r=db.plan.find(r=>r.truck===t.id)||{truck:t.id,route:trucks.findIndex(x=>x.id===t.id),count:1,allowance:''};open('adjust',{operation:'add',draft:{...r,note:''}});return;}if(a==='approval-filter'){approvalFilter=b.dataset.filter;render();return;}if(a==='staff-view'){role='ga';const url=new URL(location.href);url.searchParams.set('role','ga');url.searchParams.set('date',day);url.searchParams.set('lang',lang);url.searchParams.set('tab',tab);url.searchParams.delete('review');history.replaceState(null,'',url);notice=L('Staff view restored. Saved approvals and purchases are unchanged.','បានត្រឡប់ទៅទិដ្ឋភាពបុគ្គលិក។ ការអនុម័ត និងការទិញបានរក្សាទុកនៅដដែល។');render();return;}if(a==='language'){lang=lang==='en'?'km':'en';render();if(modal&&$('dialog').open)drawModal();return;}if(a==='close'){$('dialog').close();modal=null;return;}if(a==='menu'||a==='help'){open(a);return;}if(a==='tab'){tab=b.dataset.tab;notice='';render();}if(a==='today'){day=localDate();notice='';render();}if(a==='edit-plan'||a==='add-plan'){const r=a==='edit-plan'?db.plan.find(x=>x.truck===b.dataset.truck):{truck:trucks.find(t=>!db.plan.some(r=>r.truck===t.id))?.id,route:0,count:1,allowance:''};if(!r?.truck){notice=L('All available Logistics trucks are already in the plan.','រថយន្តដែលមានទាំងអស់ត្រូវបានបញ្ចូលក្នុងផែនការរួចហើយ។');render();return;}open('plan',{truck:a==='edit-plan'?r.truck:null,draft:{...r}});}if(a==='prepare'){if(day!==localDate()||role!=='ga'||current().preparedAt||!db.plan.length)return;save(next=>{if(day!==localDate()||!next.plan.length)throw Error();if(!next.days[day]?.preparedAt)next.days[day]={day,rows:structuredClone(next.plan),planVersion:next.planVersion,adjustments:[],preparedAt:stamp()};},L('Procurement prepared. Manage today’s trucks below.','បានរៀបចំការទិញ។ គ្រប់គ្រងរថយន្តថ្ងៃនេះខាងក្រោម។'));render();}if(a==='adjust'){if(!canChange())return;const r=effectiveRows(current()).find(r=>r.truck===b.dataset.truck);if(!r||pending(current()).some(a=>a.truck===r.truck))return;open('adjust',{operation:'adjust',before:structuredClone(r),draft:{...r,reason:'extra',note:''}});}if(a==='adjustment')open('adjustment',{id:b.dataset.id});if(a==='review-purchase'&&current().preparedAt)open('review');if(a==='purchase-detail'){if($('dialog').open)$('dialog').close();open('purchase',{id:b.dataset.id});}if(a==='previous'){historyPage--;render();}if(a==='next'){historyPage++;render();}if(a==='retry-load'){try{const raw=localStorage.getItem(key);if(raw){const p=JSON.parse(raw);if(!Array.isArray(p.plan)||!p.days||!Array.isArray(p.purchases))throw Error();db=p;}loadError=false;render();}catch(_){notice=L('Still unavailable. Existing data is unchanged.','នៅតែមិនមាន។ ទិន្នន័យដើមមិនផ្លាស់ប្តូរ។');render();}}});
window.addEventListener('storage',e=>{if(e.key!==key)return;try{const next=e.newValue?JSON.parse(e.newValue):seed();if(next.version!==1||!Array.isArray(next.plan)||!next.days||!Array.isArray(next.purchases))throw Error();db=next;render();if(modal?.type==='adjustment')drawModal();}catch(_){loadError=true;render();}});
$('dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();else modal=null;});
if(params.get('scenario')==='empty')db={...db,plan:[],days:{},purchases:[]};
if(params.get('scenario')==='rejected'){const d=current(),r=d.rows[0];d.preparedAt=stamp();d.adjustments=[{id:'sample-rejected',truck:r.truck,before:{...r},after:{truck:r.truck,runs:[...runsFor(r),{route:0,litres:20}]},delta:20,reason:'extra',note:L('Read-only rejected example; revision flow awaits review.','គំរូបដិសេធសម្រាប់មើល ការកែប្រែរង់ចាំពិនិត្យ។'),status:'rejected',initiator:'ga',createdAt:stamp()}];db.days[day]=d;}
if(params.get('scenario')==='load-error')loadError=true;
$('app').innerHTML=`<main aria-busy="true"><h1>${approvalScreen?L('Loading fuel approvals…','កំពុងផ្ទុកការអនុម័តប្រេង…'):L('Loading fuel procurement…','កំពុងផ្ទុកការទិញប្រេង…')}</h1><div class="skeleton"></div></main>`;
setTimeout(()=>{render();const review=params.get('review');if(params.get('tab')==='plan'&&role==='ga')open('manage');if(review==='purchase'&&!approvalScreen&&current().preparedAt)open('review');else if(review&&current().adjustments.some(a=>a.id===review))open('adjustment',{id:review});},350);
})();
